plugins {
    // Apply the foojay-resolver plugin to allow automatic download of JDKs
    id("org.gradle.toolchains.foojay-resolver-convention") version "1.0.0"
}

rootProject.name = "EML-HeadlessBOT"

// Single project on purpose: the only other Gradle module this repository ever had was the "lib" starter
// generated by `gradle init`, and it is NOT tracked in git. Including it made every JitPack build die with
// "Configuring project ':lib' without an existing directory is not allowed" before a single class compiled,
// so no release could be published from this repository.
